//! Mega Scale Native Type Kernel Engine (mega_kernel_b.rs) for Issue #142.

use pyo3::prelude::*;
use std::collections::HashMap;

pub struct MegaKernelB {
    pub key: String,
    pub data: HashMap<String, String>,
}

impl MegaKernelB {
    pub fn new(key: &str) -> Self {
        Self {
            key: key.to_string(),
            data: HashMap::new(),
        }
    }
}

/// Native Type Engine Rule #3501
pub fn execute_mega_type_rule_3501(engine: &mut MegaKernelB, k: &str, v: &str) -> bool {
    if k.is_empty() {
        return false;
    }
    engine.data.insert(k.to_string(), v.to_string());
    true
}

